.report-document-header { margin: 0 0 10pt !important; padding: 0 !important; border: 0 !important; background: #fff !important; color: #000 !important; break-inside: avoid; }
.report-document-header .report-document-title { margin: 0 0 18pt !important; color: #000 !important; font: bold 10pt/1.2 Arial, sans-serif !important; text-align: center !important; letter-spacing: normal !important; }
.report-document-header table { border-collapse: collapse !important; table-layout: fixed !important; min-width: 0 !important; width: 100% !important; margin: 0 !important; }
.report-document-header td { border: 0 !important; padding: 0 !important; background: #fff !important; color: #000 !important; font: 8pt/1.15 Arial, sans-serif !important; text-align: left !important; vertical-align: middle !important; }
.report-document-header .report-document-fields td { height: 12pt !important; }
.report-document-header .report-document-label { padding-right: 4pt !important; white-space: nowrap !important; }
.report-document-header .report-document-value, .report-document-header .report-document-code, .report-document-header .report-document-code-legend, .report-document-header .report-document-date-value { border: .6pt solid #000 !important; text-align: center !important; padding: 1pt 2pt !important; overflow-wrap: break-word !important; }
.report-document-header .report-document-code-legend { padding: 0 !important; font-size: 5pt !important; line-height: 1.15 !important; }
.report-document-header .report-document-date-label { white-space: nowrap !important; }
.report-document-header .report-document-date-value { height: 14pt !important; }
.report-document-context { margin: 2pt 0 5pt; color: #000; font: 7pt Arial, sans-serif; }
.report-document-header--print { display: none !important; }
@media print {
    .report-document-header--print { display: block !important; }
    .population-report > .population-report-header { display: none !important; }
}
